/**
 * src/CommonsApp.tsx — the federated root component (default export),
 * exposed as "commons/CommonsApp" and mounted directly as the standalone
 * participant bundle (see src/main.tsx). Epic #267, Story #338.
 *
 * Pins the public API + behavior the implementer must build:
 *
 *   - Default export.
 *   - Owns `I18nProvider` + `ThemeProvider` internally (mirrors
 *     RangeApp/ClioApp) — callers must NOT double-wrap with I18nProvider.
 *   - Accepts two OPTIONAL props, mirroring XApp's shape
 *     (frontends/range-mfe/src/components/x/XApp.tsx):
 *       - `basePath?: string` — the ambient mount point when embedded under
 *         a host router (e.g. "/range/exercises/ex-1/env"). When omitted,
 *         CommonsApp is standalone and falls back to its own top-level
 *         absolute /c/:exercise/* routes (reading :exercise from its OWN
 *         route params) — this is the ONLY mode with a leading "/c" prefix
 *         and a `:exercise` URL param.
 *       - `exerciseId?: string` — required for embedded use (the host
 *         already resolved which exercise). When basePath is supplied the
 *         exercise id comes from this prop, NOT from a URL param.
 *   - NO `location` prop / NO <Routes location={...}> override — CommonsApp
 *     renders normally wherever the parent mounted it, with RELATIVE route
 *     paths (no leading "/c/..." literals in embedded mode) so it never
 *     violates the React Router v6 "location pathname must begin with the
 *     portion already matched by parent routes" invariant.
 *   - Route contract (relative to whatever it's mounted under, in embedded
 *     mode; absolute /c/:exercise/* in standalone mode):
 *       "login"      -> LoginRoute
 *       "" (index) / "home" -> an authed gate:
 *           - useCommonsSession() === "loading"   -> a `role="status"`
 *             element containing `m.commons_range_commons_loading()`
 *           - useCommonsSession() === "unauthenticated" -> redirect to the
 *             login route (resolved relative to basePath, never a bare
 *             "/c/login" absolute literal when embedded)
 *           - useCommonsSession() === "ready" -> renders the browse list
 *       "c/:community" -> the community route (the nested
 *         /c/:exercise/c/:community form)
 *       "post/:id"     -> the post detail stub
 *       "*" (catch-all) -> redirect to the login route (relative)
 *   - Nothing resolves under a bare "/r/..." path — any such entry falls
 *     through the standalone catch-all to the login screen exactly like any
 *     other unknown path.
 *   - Internal Links build ABSOLUTE hrefs by prefixing with basePath (e.g.
 *     the community list's `Link to={`${base}/c/${community.name}`}`) so
 *     they never escape the host's mount point.
 */

import { render, screen, waitFor, within } from "@testing-library/react";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { http, HttpResponse } from "msw";
import { server } from "./setup";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import CommonsApp from "../src/CommonsApp";
import { clearCommonsSession } from "../src/hooks/useCommonsSession";
import indexHtml from "../index.html?raw";

beforeEach(() => {
  clearCommonsSession();
});

describe("document title", () => {
  it("declares <title>Commons — OmniCore Range</title> in index.html", () => {
    expect(indexHtml).toContain("<title>Commons — OmniCore Range</title>");
  });
});

describe("CommonsApp", () => {
  it("redirects an unauthenticated session on /c/:exercise/home to the login screen", async () => {
    server.use(
      http.get("/api/v1/commons/me", () =>
        HttpResponse.json(
          { error: { code: "unauthenticated", message: "unauthenticated" } },
          { status: 401 },
        ),
      ),
    );

    render(
      <MemoryRouter initialEntries={["/c/ex-1/home"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_login_title(),
      }),
    ).toBeInTheDocument();
  });

  it("does not redirect to login for an authenticated session on /c/:exercise/home, and does not stay stuck loading", async () => {
    // Default MSW handler returns a ready happy-path session.
    render(
      <MemoryRouter initialEntries={["/c/ex-1/home"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    // Eventually the loading status clears...
    await waitFor(() => {
      expect(screen.queryByRole("status")).not.toBeInTheDocument();
    });

    // ...and we never landed on the login screen.
    expect(
      screen.queryByRole("heading", { name: m.commons_range_commons_login_title() }),
    ).not.toBeInTheDocument();
  });

  it("shows a role=status loading message while the session is resolving", () => {
    render(
      <MemoryRouter initialEntries={["/c/ex-1/home"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(screen.getByRole("status")).toHaveTextContent(
      m.commons_range_commons_loading(),
    );
  });

  it("renders the login screen directly at /c/login", () => {
    render(
      <MemoryRouter initialEntries={["/c/login"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      screen.getByRole("heading", { name: m.commons_range_commons_login_title() }),
    ).toBeInTheDocument();
  });

  it("redirects an unknown path to the login screen", async () => {
    render(
      <MemoryRouter initialEntries={["/c/bogus"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_login_title(),
      }),
    ).toBeInTheDocument();
  });

  it("renders the CommunityRoute stub for an authenticated session, threading the :community param through as communityName", async () => {
    // Default MSW handler returns a ready happy-path session.
    render(
      <MemoryRouter initialEntries={["/c/ex-1/c/wildfireprep"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_post_listing_stub_title(),
      }),
    ).toBeInTheDocument();

    expect(
      screen.getByText(
        m.commons_range_commons_post_listing_stub_body({ name: "wildfireprep" }),
      ),
    ).toBeInTheDocument();
  });

  it("renders the PostDetailStubRoute stub for an authenticated session on /c/:exercise/post/:id", async () => {
    // Default MSW handler returns a ready happy-path session.
    render(
      <MemoryRouter initialEntries={["/c/ex-1/post/some-post-id"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_post_listing_stub_title(),
      }),
    ).toBeInTheDocument();
  });

  it("redirects an unauthenticated session on /c/:exercise/c/:community to the login screen", async () => {
    server.use(
      http.get("/api/v1/commons/me", () =>
        HttpResponse.json(
          { error: { code: "unauthenticated", message: "unauthenticated" } },
          { status: 401 },
        ),
      ),
    );

    render(
      <MemoryRouter initialEntries={["/c/ex-1/c/wildfireprep"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_login_title(),
      }),
    ).toBeInTheDocument();
  });

  it("redirects an unauthenticated session on /c/:exercise/post/:id to the login screen", async () => {
    server.use(
      http.get("/api/v1/commons/me", () =>
        HttpResponse.json(
          { error: { code: "unauthenticated", message: "unauthenticated" } },
          { status: 401 },
        ),
      ),
    );

    render(
      <MemoryRouter initialEntries={["/c/ex-1/post/some-post-id"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_login_title(),
      }),
    ).toBeInTheDocument();
  });

  it("mounts exactly one toast viewport in standalone mode", async () => {
    render(
      <MemoryRouter initialEntries={["/c/ex-1/home"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    await waitFor(() => {
      expect(
        document.body.querySelectorAll('[data-slot="toast-viewport"]'),
      ).toHaveLength(1);
    });
  });

  it("nothing resolves under a bare /r/... path — it falls through to the login screen like any unknown path", async () => {
    render(
      <MemoryRouter initialEntries={["/r/ex-1/home"]}>
        <CommonsApp />
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_login_title(),
      }),
    ).toBeInTheDocument();
    // Specifically NOT the browse grid — the /r prefix does not route to home.
    expect(
      screen.queryByRole("heading", { name: m.commons_range_commons_browse_heading() }),
    ).not.toBeInTheDocument();
  });
});

describe("CommonsApp — embedded under an ambient host router", () => {
  const EMBEDDED_BASE = "/range/exercises/ex-1/env";

  /**
   * Reproduces the real range-mfe mount shape: CommonsApp is rendered as the
   * element for an ALREADY-MATCHED ancestor splat route, exactly like
   * PlatformHost mounts it (and exactly like XApp is mounted today — see
   * frontends/range-mfe/tests/components/browser/PlatformHost.test.tsx). No
   * <Routes location={...}> override anywhere in this tree: CommonsApp must
   * render correctly nested under whatever ancestor route matched.
   */
  function renderEmbedded(initialEntry: string): ReturnType<typeof render> {
    return render(
      <MemoryRouter initialEntries={[initialEntry]}>
        <Routes>
          <Route
            path="/range/exercises/:id/env/*"
            element={<CommonsApp basePath={EMBEDDED_BASE} exerciseId="ex-1" />}
          />
        </Routes>
      </MemoryRouter>,
    );
  }

  it("does not throw and logs no React Router location-mismatch error when mounted under a nested ambient route", async () => {
    const consoleErrorSpy = vi
      .spyOn(console, "error")
      .mockImplementation(() => undefined);

    // The ORIGINAL BUG: overriding <Routes location> with a synthetic
    // "/c/ex-1/home" pathname while the ambient ancestor route has already
    // matched "/range/exercises/ex-1/env" throws
    // "the location pathname must begin with the portion of the URL
    // pathname that was matched by all parent routes". Rendering here must
    // not throw AND must not log that invariant violation.
    expect(() => renderEmbedded(EMBEDDED_BASE)).not.toThrow();

    // No session bootstrap in embedded mode — the grid renders directly,
    // with no loading-status wait gating on a session fetch.
    await screen.findByRole("heading", {
      name: m.commons_range_commons_browse_heading(),
    });

    for (const call of consoleErrorSpy.mock.calls) {
      const message = String(call[0]);
      expect(message).not.toMatch(/location pathname must begin with/i);
    }

    consoleErrorSpy.mockRestore();
  });

  it("shows the community browse list directly, with no session bootstrap at all", async () => {
    renderEmbedded(EMBEDDED_BASE);

    // Embedded mode never gates on useCommonsSession()/AuthedShell — the
    // grid must appear without ever passing through a role="status"
    // loading screen tied to a session fetch.
    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_browse_heading(),
      }),
    ).toBeInTheDocument();
  });

  it("renders the browse grid even when GET /api/v1/commons/me would 401 — embedded mode never calls it", async () => {
    // Embedded mode has no commons_session-style bootstrap at all — this test
    // proves even a hostile /commons/me response must NOT affect the
    // embedded surface, because embedded mode is wired to fetch via the
    // range route instead and never touches /commons/me.
    let commonsMeCalled = false;
    let rangeCommunitiesCalled = false;
    server.use(
      http.get("/api/v1/commons/me", () => {
        commonsMeCalled = true;
        return HttpResponse.json(
          { error: { code: "unauthenticated", message: "unauthenticated" } },
          { status: 401 },
        );
      }),
      http.get("/api/v1/range/exercises/:id/communities", () => {
        rangeCommunitiesCalled = true;
        return HttpResponse.json({
          data: {
            communities: [
              {
                id: "sub-1",
                org_id: "org-1",
                exercise_id: "ex-1",
                name: "wildfireprep",
                display_name: "c/wildfireprep",
                description: "Coordination for wildfire response",
                member_count: 4204,
              },
            ],
            next_page_token: "",
          },
        });
      }),
