/**
 * src/styles/index.css — theme-token coverage for commons-mfe.
 *
 * Phase 4 background: commons-mfe shipped a LIVE bug on this branch — its
 * Tailwind config was already on the new "Indigo Atlas" blue ramp while this
 * file's `:root` (light) block still carried the OLD focus-ring color
 * (`26 79 214` / `#1A4FD6`) instead of the canonical `39 66 201` / `#2742C9`,
 * and its `--cog-canvas`/`--cog-surface-*` set had drifted from the other
 * 13 MFEs' consensus values (same class of drift kite-mfe carried — see
 * that package's own collapse comment). The PREVIOUS version of this suite
 * could not have caught the focus bug: it only asserted the two
 * `--commons-*` tokens' literal values (a hardcoded copy of what the file
 * already said, so it could never disagree with a wrong file) and never
 * looked at any `--cog-*` token at all.
 *
 * Phase 4 then collapsed every MFE's hand-maintained `--cog-*`/
 * `--commons-accent` theme-var block onto one generated, normative
 * stylesheet: frontends/design-tokens/dist/base.css (13-MFE consensus
 * values, sourced from tokens.json's `$themeValues`). commons-mfe's
 * src/styles/index.css is now just `@import ".../base.css";` plus its
 * genuinely local tail — `--commons-downvote` (DESIGN.md's Commons palette
 * section; `--commons-accent` was centralized into base.css itself, since
 * this package's copy was byte-identical to range-mfe's).
 *
 * This suite therefore checks THREE things:
 *   1. index.css actually imports base.css (the collapse mechanism itself),
 *      and does NOT re-declare any `--cog-*`/`--commons-accent` var locally
 *      — a local redeclaration would silently shadow the shared value and
 *      defeat the whole point of collapsing onto one source.
 *   2. `--commons-downvote` (the one token that stays genuinely local) is
 *      still declared correctly in all three theme blocks of index.css.
 *   3. base.css itself — the new single source of truth — carries the
 *      canonical `--cog-focus` value (regression guard for the #1A4FD6 live
 *      bug) in all three theme blocks, carries `--commons-accent` byte-
 *      identical to what commons used to declare locally, and its border/
 *      divider tokens clear the WCAG 3:1 UI floor Task 5.2 raised them to.
 *      base.css is generated (owned by frontends/design-tokens/**, not this
 *      package) but commons-mfe's rendered theme now depends entirely on
 *      it, so this suite reads it directly rather than trusting it blindly.
 *
 * base.css went through two more bugs after the collapse landed here, both
 * now fixed upstream: (a) an early draft's header comment contained a
 * literal star-slash inside prose, which closed the CSS block comment early
 * and broke the whole file's parse; (b) an early draft moved the 8
 * `@fontsource/*` imports into base.css itself, but postcss resolves a bare
 * specifier relative to the file containing the `@import`, and
 * frontends/design-tokens has no package.json/node_modules (deliberately,
 * to stay out of the 17-MFE fan-out and Trivy scan) — so every consuming
 * MFE's build failed with ENOENT. Fonts now stay in each MFE's own
 * index.css, commons included; see the fonts describe block below for the
 * regression guard.
 *
 * The CSS content is read via Vite's `?raw` import mechanism (see
 * frontends/kite-mfe/tests/rtl-logical-props.test.ts for the repo's `?raw`
 * idiom) — no fs/path/node types needed.
 */

import indexCss from "../src/styles/index.css?raw";
import baseCss from "../../design-tokens/dist/base.css?raw";

/**
 * extractBlock — returns the content of the first brace-balanced block whose
 * opening `{` appears at or after `fromIndex`, starting the scan at
 * `startMarker`. Handles the nested-brace case (the @media block wraps
 * another rule) by counting braces rather than matching to the first `}`.
 */
function extractBlock(source: string, startMarker: string, fromIndex = 0): string {
  const markerIndex = source.indexOf(startMarker, fromIndex);
  if (markerIndex === -1) {
    throw new Error(`marker not found: ${startMarker}`);
  }
  const openIndex = source.indexOf("{", markerIndex);
  if (openIndex === -1) {
    throw new Error(`no opening brace after marker: ${startMarker}`);
  }
  let depth = 0;
  for (let i = openIndex; i < source.length; i += 1) {
    if (source[i] === "{") depth += 1;
    if (source[i] === "}") {
      depth -= 1;
      if (depth === 0) {
        return source.slice(openIndex + 1, i);
      }
    }
  }
  throw new Error(`unbalanced braces after marker: ${startMarker}`);
}

/** Reads a `--token: r g b;` RGB-triple declaration out of a CSS block. */
function readTriple(block: string, token: string): [number, number, number] {
  const match = new RegExp(`--${token}:\\s*(\\d+)\\s+(\\d+)\\s+(\\d+)\\s*;`).exec(block);
  if (!match) {
    throw new Error(`--${token} not found (or not a bare RGB triple) in block`);
  }
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

function tripleToHex([r, g, b]: [number, number, number]): string {
  return `#${[r, g, b].map((c) => c.toString(16).padStart(2, "0")).join("").toUpperCase()}`;
}

// ---------------------------------------------------------------------------
// WCAG 2.x contrast-ratio math — stdlib only, deliberately re-implemented
// rather than imported from frontends/design-tokens/lib/contrast-math.mjs
// (this file owns no path under frontends/design-tokens/**); see
// frontends/ui/tests/token-contrast.test.ts's header for the precedent (a
// sibling initiative makes the identical call for the identical reason).
// ---------------------------------------------------------------------------
function channelLuminance(c: number): number {
  const cs = c / 255;
  return cs <= 0.03928 ? cs / 12.92 : ((cs + 0.055) / 1.055) ** 2.4;
}

function relativeLuminance([r, g, b]: [number, number, number]): number {
  return 0.2126 * channelLuminance(r) + 0.7152 * channelLuminance(g) + 0.0722 * channelLuminance(b);
}

function contrastRatio(a: [number, number, number], b: [number, number, number]): number {
  const lA = relativeLuminance(a);
  const lB = relativeLuminance(b);
  const [lighter, darker] = lA >= lB ? [lA, lB] : [lB, lA];
  return (lighter + 0.05) / (darker + 0.05);
}

const UI_FLOOR = 3.0; // design.md §1.1 "UI / icon / border contrast | ≥ 3 : 1"

// Canonical focus-ring hex per docs/design/design.md's Focus ring row
// ("light = Cog Blue 600 (#2742C9), dark = Amber 600 (#FBBF24)") — the exact
// value this suite's rewrite exists to keep commons-mfe pinned to.
const CANONICAL_FOCUS_LIGHT: [number, number, number] = [39, 66, 201]; // #2742C9
const CANONICAL_FOCUS_DARK: [number, number, number] = [251, 191, 36]; // #FBBF24

// The 14 `--cog-*` theme-var names base.css's @layer base :root/dark/media
// blocks each carry, plus --commons-accent (centralized here from commons).
// Used to assert index.css does NOT locally redeclare (and thus shadow) any
// of them.
const SHARED_THEME_VARS = [
  "cog-canvas",
  "cog-surface",
  "cog-surface-subtle",
  "cog-surface-muted",
  "cog-text-primary",
  "cog-text-secondary",
  "cog-text-tertiary",
  "cog-text-eyebrow",
  "cog-warning",
  "cog-border",
  "cog-divider",
  "cog-border-emphasized",
  "cog-focus",
  "commons-accent",
];

describe("src/styles/index.css imports the shared base stylesheet", () => {
  it("imports frontends/design-tokens/dist/base.css (the Phase-4 collapse target)", () => {
    expect(indexCss).toContain('@import "../../../design-tokens/dist/base.css";');
  });

  it("the import path resolves from frontends/commons-mfe/src/styles/ to frontends/design-tokens/dist/base.css", () => {
    // Sanity-checks the fixture: if the relative path were wrong, Vite's
    // own `?raw` import of base.css above would already have thrown at
    // module-load time. This assertion documents *why* it didn't: three
    // `../` levels (styles -> src -> commons-mfe -> frontends) then back
    // down into design-tokens/dist.
    expect(baseCss.length).toBeGreaterThan(0);
    expect(baseCss).toContain("--cog-focus: 39 66 201");
  });

  it.each(SHARED_THEME_VARS)("does NOT locally redeclare --%s (would shadow the shared value)", (token) => {
    // Matches the local file's own custom-property declarations, not the
    // @import line or prose comments mentioning the token name.
    const declPattern = new RegExp(`--${token}:\\s*\\S`);
    expect(declPattern.test(indexCss)).toBe(false);
  });
});

describe("src/styles/index.css keeps its own @fontsource imports (fonts stay MFE-local, NOT centralized in base.css)", () => {
  it("declares all 8 self-hosted font imports (Inter 300/400/500/600/700 + JetBrains Mono 400/500/700)", () => {
    for (const weight of ["300", "400", "500", "600", "700"]) {
      expect(indexCss).toContain(`@import "@fontsource/inter/${weight}.css";`);
    }
    for (const weight of ["400", "500", "700"]) {
      expect(indexCss).toContain(`@import "@fontsource/jetbrains-mono/${weight}.css";`);
    }
  });

  it("base.css does NOT declare any @fontsource import (design-tokens has no package.json/node_modules to resolve a bare specifier from)", () => {
    // base.css's own header explains the "@fontsource/inter" ENOENT failure
    // in prose, so this checks for an actual `@import` statement, not the
    // substring "@fontsource" (which the explanatory comment legitimately
    // contains).
    expect(baseCss).not.toMatch(/@import\s+["']@fontsource\//);
  });
});

describe("src/styles/index.css theme blocks — --commons-downvote (genuinely local)", () => {
  it("has exactly three theme blocks (:root, [data-theme=dark], and the prefers-color-scheme media query)", () => {
    const rootMatches = indexCss.match(/:root\s*\{/g) ?? [];
    const darkThemeMatches = indexCss.match(/\[data-theme="dark"\]/g) ?? [];
    const mediaMatches = indexCss.match(/@media \(prefers-color-scheme: dark\)/g) ?? [];

    expect(rootMatches.length).toBe(1);
    expect(darkThemeMatches.length).toBe(1);
    expect(mediaMatches.length).toBe(1);
  });

  it("declares --commons-downvote with the light-default RGB triple in the :root block", () => {
    const rootBlock = extractBlock(indexCss, ":root {");
    expect(rootBlock).toContain("--commons-downvote: 83 97 168");
  });

  it("declares --commons-downvote with the dark RGB triple in the [data-theme=\"dark\"], .dark block", () => {
    const darkBlock = extractBlock(indexCss, '[data-theme="dark"],');
    expect(darkBlock).toContain("--commons-downvote: 124 136 212");
  });

  it("declares --commons-downvote with the SAME dark RGB triple inside the @media (prefers-color-scheme: dark) block, nested under :root:not([data-theme=\"light\"])", () => {
    const mediaBlock = extractBlock(indexCss, "@media (prefers-color-scheme: dark) {");
    expect(mediaBlock).toContain(':root:not([data-theme="light"])');
    expect(mediaBlock).toContain("--commons-downvote: 124 136 212");
  });
});

describe("shared base.css — --commons-accent centralized byte-identical to commons's former local value", () => {
  it("light :root carries #1F7A54 (31 122 84), dark carries #4FBF8B (79 191 139)", () => {
    const rootBlock = extractBlock(baseCss, ":root {");
    const darkBlock = extractBlock(baseCss, '[data-theme="dark"],');
    expect(rootBlock).toContain("--commons-accent: 31 122 84");
    expect(darkBlock).toContain("--commons-accent: 79 191 139");
  });
});

describe("shared base.css — --cog-focus pinned to the canonical design.md value (regression guard for the #1A4FD6 live bug)", () => {
  it("light :root focus ring is #2742C9 (Indigo Atlas Cog Blue 600), not the old #1A4FD6", () => {
    const rootBlock = extractBlock(baseCss, ":root {");
    const focus = readTriple(rootBlock, "cog-focus");
    expect(tripleToHex(focus)).toBe(tripleToHex(CANONICAL_FOCUS_LIGHT));
  });

  it("dark [data-theme=dark] focus ring is #FBBF24 (Amber 600)", () => {
    const darkBlock = extractBlock(baseCss, '[data-theme="dark"],');
    const focus = readTriple(darkBlock, "cog-focus");
    expect(tripleToHex(focus)).toBe(tripleToHex(CANONICAL_FOCUS_DARK));
  });

  it("the @media (prefers-color-scheme: dark) block carries the SAME dark focus ring", () => {
    const mediaBlock = extractBlock(baseCss, "@media (prefers-color-scheme: dark) {");
    const focus = readTriple(mediaBlock, "cog-focus");
    expect(tripleToHex(focus)).toBe(tripleToHex(CANONICAL_FOCUS_DARK));
  });

  it("--cog-focus-halo's rgba() literal matches --cog-focus in both themes (no orphaned old-color halo)", () => {
    const rootBlock = extractBlock(baseCss, ":root {");
    const darkBlock = extractBlock(baseCss, '[data-theme="dark"],');
    expect(rootBlock).toContain("rgba(39, 66, 201, 0.25)");
    expect(darkBlock).toContain("rgba(131, 179, 252, 0.25)");
  });
});

describe("shared base.css — border/divider tokens clear the WCAG 3:1 UI-contrast floor against every adjacent surface (Task 5.2)", () => {
  it.each([
    ["light", ":root {"],
    ["dark", '[data-theme="dark"],'],
  ] as const)("%s theme: cog-border and cog-divider vs cog-canvas and cog-surface", (_theme, marker) => {
    const block = extractBlock(baseCss, marker);
    const canvas = readTriple(block, "cog-canvas");
    const surface = readTriple(block, "cog-surface");
    const border = readTriple(block, "cog-border");
    const divider = readTriple(block, "cog-divider");
    const borderEmphasized = readTriple(block, "cog-border-emphasized");

    for (const [name, rgb] of [
      ["cog-border", border],
      ["cog-divider", divider],
      ["cog-border-emphasized", borderEmphasized],
    ] as const) {
      expect(contrastRatio(rgb, canvas), `${name} vs cog-canvas`).toBeGreaterThanOrEqual(UI_FLOOR);
      expect(contrastRatio(rgb, surface), `${name} vs cog-surface`).toBeGreaterThanOrEqual(UI_FLOOR);
    }
  });
});



