/**
 * CommonsApp.bridge.test.tsx — Epic #267, two-way address-bar <-> route bridge
 * for the in-shell Commons tab. Mirrors range-mfe's XApp.bridge.test.tsx shape
 * as closely as sensible for Commons' much simpler path space (no id<->handle
 * translation — the public path IS the internal relative route path, 1:1).
 *
 * Tests EmbeddedCommonsRoutes via CommonsApp mounted with basePath +
 * exerciseId, passing `path` / `onPathChange` props (CommonsAppProps).
 *
 * DRIVE (shell -> Commons):
 *  - path=""              -> browse-grid home renders.
 *  - path="c/opsec_talk"  -> community stub for "opsec_talk" renders.
 *  - path="post/p-1"      -> post detail stub renders.
 *  - Coordinator-required: mounting with an initial community path then
 *    re-rendering with path="" drives back to the browse-grid home (not
 *    left on the community) — mirrors the omnibox "commons.range" bare-host
 *    case from BrowserShell.commons.bridge.test.tsx.
 *
 * EMIT (Commons -> shell):
 *  - Clicking a community card calls onPathChange("c/<name>").
 *  - No onPathChange calls fire when path is already in sync with the
 *    current internal location (echo-loop guard).
 *  - No-infinite-loop regression test via a local ControlledCommonsApp
 *    wrapper mirroring onPathChange back into path state.
 *  - "Back to communities" link stays present when viewing an embedded
 *    community/post.
 */

import { useState, type ReactElement } from "react";
import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { http, HttpResponse } from "msw";
import { server } from "./setup";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import CommonsApp from "../src/CommonsApp";
import { clearCommonsSession } from "../src/hooks/useCommonsSession";

const EMBEDDED_BASE = "/range/exercises/ex-1/env";
const EXERCISE_ID = "ex-1";

beforeEach(() => {
  clearCommonsSession();
});

/**
 * Renders CommonsApp embedded under an ambient host router, exactly like
 * PlatformHost mounts it — no <Routes location={...}> override anywhere.
 */
function renderEmbedded(opts: {
  readonly path?: string;
  readonly onPathChange?: (p: string) => void;
  readonly initialEntry?: string;
}): ReturnType<typeof render> {
  const { path, onPathChange, initialEntry = EMBEDDED_BASE } = opts;
  return render(
    <MemoryRouter initialEntries={[initialEntry]}>
      <Routes>
        <Route
          path="/range/exercises/:id/env/*"
          element={
            <CommonsApp
              basePath={EMBEDDED_BASE}
              exerciseId={EXERCISE_ID}
              path={path}
              onPathChange={onPathChange}
            />
          }
        />
      </Routes>
    </MemoryRouter>,
  );
}

// ─── DRIVE: shell -> Commons ──────────────────────────────────────────────────

describe("CommonsApp bridge — path prop drives internal navigation (shell->Commons)", () => {
  it("path='' renders the browse-grid home", async () => {
    renderEmbedded({ path: "" });
    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_browse_heading(),
      }),
    ).toBeInTheDocument();
  });

  it("path='c/opsec_talk' renders the community stub for opsec_talk", async () => {
    renderEmbedded({ path: "c/opsec_talk" });
    expect(
      await screen.findByText(
        m.commons_range_commons_post_listing_stub_body({ name: "opsec_talk" }),
      ),
    ).toBeInTheDocument();
  });

  it("path='post/p-1' renders the post detail stub", async () => {
    renderEmbedded({ path: "post/p-1" });
    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_post_listing_stub_title(),
      }),
    ).toBeInTheDocument();
  });

  it("coordinator-required: re-rendering from an initial community path down to path='' drives back to the browse-grid home", async () => {
    const { rerender } = renderEmbedded({ path: "c/opsec_talk" });

    // First confirm we're on the community stub.
    expect(
      await screen.findByText(
        m.commons_range_commons_post_listing_stub_body({ name: "opsec_talk" }),
      ),
    ).toBeInTheDocument();

    // Re-render with path="" — must drive all the way back to home, not stay
    // on the community.
    rerender(
      <MemoryRouter initialEntries={[EMBEDDED_BASE]}>
        <Routes>
          <Route
            path="/range/exercises/:id/env/*"
            element={
              <CommonsApp
                basePath={EMBEDDED_BASE}
                exerciseId={EXERCISE_ID}
                path=""
              />
            }
          />
        </Routes>
      </MemoryRouter>,
    );

    expect(
      await screen.findByRole("heading", {
        name: m.commons_range_commons_browse_heading(),
      }),
    ).toBeInTheDocument();
    expect(
      screen.queryByText(
        m.commons_range_commons_post_listing_stub_body({ name: "opsec_talk" }),
      ),
    ).not.toBeInTheDocument();
  });
});

// ─── EMIT: Commons -> shell ───────────────────────────────────────────────────

describe("CommonsApp bridge — onPathChange emits the canonical path (Commons->shell)", () => {
  it("clicking a community card in the grid calls onPathChange('c/<name>')", async () => {
    const user = userEvent.setup();
    const onPathChange = vi.fn<(p: string) => void>();
    renderEmbedded({ path: "", onPathChange });

    const list = await screen.findByRole("list", {
      name: m.commons_range_commons_grid_label({ count: 2 }),
    });
    const links = within(list).getAllByRole("link");
    expect(links.length).toBeGreaterThan(0);

    await user.click(links[0]);

    await waitFor(() => {
      expect(onPathChange).toHaveBeenCalledWith("c/wildfireprep");
    });
  });

  it("does NOT call onPathChange when the incoming path matches the current location (echo-loop guard)", async () => {
    const onPathChange = vi.fn<(p: string) => void>();
    const { rerender } = renderEmbedded({ path: "", onPathChange });

    await screen.findByRole("heading", {
      name: m.commons_range_commons_browse_heading(),
    });

    const callCountAfterMount = onPathChange.mock.calls.length;

    // Re-render with the SAME path="" — must not call onPathChange again.
    rerender(
      <MemoryRouter initialEntries={[EMBEDDED_BASE]}>
        <Routes>
          <Route
            path="/range/exercises/:id/env/*"
            element={
              <CommonsApp
                basePath={EMBEDDED_BASE}
                exerciseId={EXERCISE_ID}
                path=""
                onPathChange={onPathChange}
              />
            }
          />
        </Routes>
      </MemoryRouter>,
    );

    await waitFor(() => {
      // give any effects a chance to run
    });

    expect(onPathChange.mock.calls.length).toBe(callCountAfterMount);
  });
});

// ─── No-infinite-loop regression (mirrors XApp's ControlledXApp/NavCapture) ──

/**
 * ControlledCommonsApp — holds `path` in React state and mirrors onPathChange
 * back into it (like the real BrowserShell does). Records every emitted path
 * into the shared `emits` array so the test can assert bounded call counts.
 */
function ControlledCommonsApp({
  emits,
}: {
  readonly emits: string[];
}): ReactElement {
  const [path, setPath] = useState("");
  return (
    <CommonsApp
      basePath={EMBEDDED_BASE}
      exerciseId={EXERCISE_ID}
      path={path}
      onPathChange={(p: string) => {
        emits.push(p);
        setPath(p); // mirror, like the real shell
      }}
    />
  );
}

