import "@testing-library/jest-dom/vitest";
import "vitest-axe/extend-expect";
import { setupServer } from "msw/node";
import { handlers } from "./msw/handlers";
import { afterAll, afterEach, beforeAll } from "vitest";

// jsdom does not implement window.matchMedia. Stub it globally so any
// component that calls matchMedia (e.g. ThemeProvider) doesn't crash.
Object.defineProperty(window, "matchMedia", {
  writable: true,
  value: (query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addEventListener: () => undefined,
    removeEventListener: () => undefined,
    dispatchEvent: () => false,
  }),
});

// jsdom does not implement Element.prototype.scrollIntoView. Stub it as a
// no-op so components that call it don't crash.
if (!Element.prototype.scrollIntoView) {
  Element.prototype.scrollIntoView = function () {};
}

// MSW node server — intercepts fetch() calls in jsdom so component tests
// don't need to reach the real range-bff.
export const server = setupServer(...handlers);

beforeAll(() => server.listen({ onUnhandledRequest: "warn" }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());


